package local.yxp;

import static local.yxp.BattleTestDecks.allowRepeatedSingleUseCards;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static local.yxp.Models.*;
class TalentEffectsTest {
 final Rules rules=new Rules();final Engine engine=new Engine(rules);
 Player p(String id,int card,List<Integer> talents,Map<String,Integer> buffs){return new Player(id,id,0,400,800,10,0,0,Collections.nCopies(8,card),talents,buffs,List.of());}
 Player hero(Player p,int id){return new Player(p.id(),p.name(),id,p.hp(),p.maxHp(),p.anima(),p.defense(),p.swordIntent(),p.cards(),p.talentIds(),p.buffs());}
 Result run(String stage,Player a,Player b){return engine.simulate(new Request(Rules.ID,"STANDARD",stage,"A",List.of(allowRepeatedSingleUseCards(a),b)));}
 Player idle(){return p("B",1000005,List.of(),Map.of());}
 Event event(Result r,int turn,String type){return r.events().stream().filter(e->e.turn()==turn&&e.type().equals(type)).findFirst().orElseThrow();}
 State end(Result r,int turn,int who){return event(r,turn,"TURN_END").states().get(who);}
 State opened(Result r){return r.events().stream().filter(e->e.type().equals("TALENT")).reduce((a,b)->b).orElseThrow().states().getFirst();}
 @Test void entireCatalogRetainsExplicitCoverage(){assertEquals(479,rules.talentCatalog.size());assertEquals(rules.talentCatalog.stream().filter(t->Boolean.TRUE.equals(t.get("supported"))).count(),rules.talents.size());assertEquals(24,rules.characters.size());assertTrue(rules.characters.stream().allMatch(c->c.containsKey("sect")&&c.containsKey("talents")));assertTrue(rules.talents.stream().allMatch(t->!t.description().isBlank()));}
 @Test void everySupportedTalentRunsAcrossSixMechanismDecksAndValidStages(){int count=0;for(var t:rules.talents)for(int card:new int[]{1000005,1000001,4000001,7000009,10000006,10000018})for(String stage:t.openingOnly()?List.of("PRE_OPENING"):List.of("PRE_OPENING","POST_OPENING")){
  var a=p("A",card,List.of(t.id()),Map.of("physique",20,"physiqueCap",30,"forceCap",6));var req=new Request(Rules.ID,"STANDARD",stage,"A",List.of(a,idle()));var r=assertDoesNotThrow(()->engine.simulateForValidation(req),t.id()+" card="+card+" "+stage);assertEquals("COMPLETED",r.status());for(var state:r.finalStates()){assertTrue(state.hp()<=state.maxHp());assertTrue(state.defense()>=0&&state.anima()>=0);}count++;
 }assertTrue(count>=800);}
 @Test void openingVariantsUseTheirOwnValues(){for(int id:new int[]{13,10013,20013,30013}){var r=run("PRE_OPENING",p("A",1000005,List.of(id),Map.of()),idle());assertEquals(10+rules.talentById.get(id).param(0),opened(r).anima());}}
 @Test void onlyOpeningTalentsAreRejectedForPostSnapshots(){var e=assertThrows(Engine.Rejected.class,()->run("POST_OPENING",p("A",1000005,List.of(13),Map.of()),idle()));assertEquals("INVALID_INPUT",e.status);assertDoesNotThrow(()->run("POST_OPENING",p("A",1000005,List.of(61),Map.of()),idle()));}
 @Test void mismatchedCharacterIsRejected(){var e=assertThrows(Engine.Rejected.class,()->run("POST_OPENING",hero(p("A",1000005,List.of(61),Map.of()),1000001),idle()));assertEquals("INVALID_INPUT",e.status);}
 @Test void mismatchedSectIsRejected(){assertThrows(Engine.Rejected.class,()->run("POST_OPENING",hero(p("A",1000005,List.of(69),Map.of()),4000001),idle()));}
 @Test void unsupportedTalentIsNeverSilentlyApplied(){var e=assertThrows(Engine.Rejected.class,()->run("PRE_OPENING",p("A",1000005,List.of(259),Map.of()),idle()));assertEquals("UNSUPPORTED",e.status);}
 @Test void choosingCharacterAloneDoesNotGrantUnownedTalents(){var r=run("PRE_OPENING",hero(p("A",1000005,List.of(),Map.of()),2000004),idle());assertFalse(r.events().stream().anyMatch(e->e.type().equals("TALENT")));assertEquals(0,end(r,1,0).statuses().get("hexagram"));}
 @Test void astrologerTriggersWhenOpeningGrantsHexagram(){var s=opened(run("PRE_OPENING",p("A",1000005,List.of(30,61),Map.of()),idle()));assertEquals(1,s.statuses().get("hexagram"));assertEquals(1,s.statuses().get("starPower"));}
 @Test void starTalentUsesPhysicalSeventhSlotAndDuplicateGrantsAnima(){var a=p("A",1000005,List.of(33),Map.of("starMask",64));var s=opened(run("PRE_OPENING",a,idle()));assertEquals(64,s.statuses().get("starMask"));assertEquals(11,s.anima());}
 @Test void newStarDiscFillsFirstSevenWithoutDuplicateRewards(){var s=opened(run("PRE_OPENING",p("A",1000005,List.of(249),Map.of("starMask",36)),idle()));assertEquals(127,s.statuses().get("starMask"));assertEquals(10,s.anima());}
 @Test void defenseTalentAddsOncePerGain(){assertEquals(6,end(run("POST_OPENING",p("A",1000005,List.of(38),Map.of()),idle()),1,0).defense());}
 @Test void overflowHealingTriggersSnowFeatherDefense(){var a=new Player("A","A",0,800,800,10,0,0,Collections.nCopies(8,2000001),List.of(64),Map.of());assertEquals(1,end(run("POST_OPENING",a,idle()),1,0).defense());}
 @Test void attacklessTurnTriggersUnsheathedSword(){assertEquals(8,end(run("POST_OPENING",p("A",1000005,List.of(66),Map.of()),idle()),1,0).defense());}
 @Test void iceBladeAddsDefenseBeforeEveryHit(){var s=end(run("POST_OPENING",p("A",1000013,List.of(68),Map.of()),idle()),1,0);assertEquals(3,s.defense());}
 @Test void fireBladeReducesCapAndTriggersSharpnessThroughDefense(){var b=new Player("B","B",0,400,800,0,100,0,Collections.nCopies(8,1000005),List.of(),Map.of());var r=run("POST_OPENING",p("A",1000004,List.of(67),Map.of("sharpness",3)),b);var hit=event(r,1,"ATTACK");assertEquals(799,hit.states().get(1).maxHp());assertEquals(397,hit.states().get(1).hp());}
 @Test void allFourElementCommunicationVariantsHaveDifferentRewards(){for(int id:new int[]{79,10079,20079,30079}){var s=end(run("POST_OPENING",p("A",7000009,List.of(id),Map.of()),idle()),1,0);int n=rules.talentById.get(id).param(0);switch(id){case 79 -> assertEquals(n,s.defense());case 10079 -> assertEquals(400+n,s.hp());case 20079 -> assertEquals(n,s.statuses().get("sharpness"));case 30079 -> assertEquals(11+n,s.anima());}}}
 @Test void essenceOnlyRewardsFirstActivation(){var r=run("POST_OPENING",p("A",7000001,List.of(112),Map.of()),idle());assertEquals(4,end(r,1,0).statuses().get("sharpness"));assertEquals(0,end(r,3,0).statuses().get("sharpness"));}
 @Test void elementalGatheringOnlyTriggersAtFirstActivation(){var r=run("POST_OPENING",p("A",7000001,List.of(202),Map.of()),idle());assertEquals(11,end(r,1,0).anima());assertEquals(11,end(r,3,0).anima());}
 @Test void woodBreathingActivatesForNonElementalCard(){var s=end(run("POST_OPENING",p("A",1000005,List.of(200),Map.of()),idle()),1,0);assertEquals(802,s.maxHp());assertEquals(1,s.statuses().get("woodActivation"));}
 @Test void physiqueDefenseHasPerGainLimit(){var s=end(run("POST_OPENING",p("A",10000037,List.of(184),Map.of("physiqueCap",100)),idle()),1,0);assertEquals(rules.byId.get(10000037).physique(),s.defense());}
 @Test void negativeStatusHealsByActualLayers(){var s=end(run("POST_OPENING",p("A",10000018,List.of(177),Map.of()),idle()),1,0);assertEquals(403,s.hp());}
 @Test void lifeReplacesMissingAnimaOnlyIfItLeavesLife(){var a=new Player("A","A",0,20,100,0,0,0,Collections.nCopies(8,10000029),List.of(153),Map.of());var r=run("POST_OPENING",a,idle());assertTrue(r.events().stream().anyMatch(e->e.turn()==1&&e.type().equals("CARD_PLAY")));assertFalse(r.events().stream().anyMatch(e->e.turn()==1&&e.type().equals("ANIMA_SHORTAGE")));}
 @Test void lifeReplacementCannotSpendTheLastLife(){var cost=-rules.byId.get(10000029).anima()*3;var a=new Player("A","A",0,cost,100,0,0,0,Collections.nCopies(8,10000029),List.of(153),Map.of());assertTrue(run("POST_OPENING",a,idle()).events().stream().anyMatch(e->e.turn()==1&&e.type().equals("ANIMA_SHORTAGE")));}
 @Test void splitFistSpendsCapInsteadOfHpLossHistory(){var s=end(run("POST_OPENING",p("A",10000001,List.of(174),Map.of()),idle()),1,0);assertEquals(797,s.maxHp());assertEquals(400,s.hp());assertEquals(0,s.statuses().get("hpLost"));}
 @Test void animaWineUsesSeparateCapAndHealingAmounts(){var s=end(run("POST_OPENING",p("A",4000001,List.of(261),Map.of()),idle()),1,0);assertEquals(805,s.maxHp());assertEquals(402,s.hp());}
 @Test void windPhysiqueBudgetIsPerBattle(){var r=run("POST_OPENING",p("A",10000032,List.of(267),Map.of("physiqueCap",100)),idle());assertEquals(2,end(r,1,0).statuses().get("physique"));assertEquals(3,end(r,3,0).statuses().get("physique"));assertEquals(3,end(r,5,0).statuses().get("physique"));}
 @Test void animaChaseHasOneBattleCharge(){var a=p("A",10020026,List.of(47),Map.of());var r=run("POST_OPENING",a,idle());assertEquals(1,end(r,1,0).statuses().get("talentAnimaChaseUsed"));assertEquals(1,r.events().stream().flatMap(e->e.changes().stream()).filter(c->c.attribute().equals("talentAnimaChaseUsed")&&c.after()>c.before()).count());}
 @Test void hexSelfGrowthSettlesAtOwnTurnEnd(){var s=end(run("POST_OPENING",p("A",10000032,List.of(195),Map.of()),idle()),1,0);assertEquals(1,s.statuses().get("hexagram"));assertEquals(0,s.statuses().get("talentHexPending"));}
 @Test void mirrorOnlyReflectsFirstStatusGain(){var s=end(run("POST_OPENING",p("A",10000018,List.of(256),Map.of()),idle()),1,1);assertEquals(2,s.statuses().get("vulnerability"));}
 @Test void poisonFlameAddsOneInjuryLayer(){var r=run("POST_OPENING",p("A",3000015,List.of(251),Map.of()),idle());assertEquals(3,end(r,1,1).statuses().get("internalInjury"));}
 @Test void fullAndCompactTalentPathsAgree(){var req=new Request(Rules.ID,"STANDARD","PRE_OPENING","A",List.of(p("A",4000001,List.of(30,61,36,195),Map.of()),idle()));assertEquals(engine.simulate(req).finalStates(),engine.simulateForValidation(req).finalStates());}
 @Test void feedbackLoopIsExplicitlyRejectedInsteadOfOverflowingTheStack(){var e=assertThrows(Engine.Rejected.class,()->run("POST_OPENING",p("A",4000001,List.of(36),Map.of("animaToHexagram",1)),idle()));assertEquals("RESOLUTION_LIMIT",e.status);}
 @Test void forceOverflowAndForceProtectionUseRequestedGain(){var s=end(run("POST_OPENING",p("A",10000010,List.of(257),Map.of("force",6)),idle()),1,0);assertEquals(6,s.statuses().get("force"));assertEquals(4,s.defense());}
 Engine.Fighter[] pair(List<Integer> talents,Map<String,Integer> buffs){var a=new Engine.Fighter(p("A",1000005,talents,buffs));var b=new Engine.Fighter(idle());var res=new Engine.Resolution();res.fighters=new Engine.Fighter[]{a,b};res.log=new ArrayList<>();for(var f:res.fighters){f.rules=rules;f.resolution=res;}a.opponent=b;b.opponent=a;return res.fighters;}
 @Test void eclipseUsesEachVariantsOpeningValue(){for(int id:new int[]{103,10103,20103,30103}){var r=run("PRE_OPENING",p("A",1000005,List.of(id),Map.of()),idle());assertEquals(rules.talentById.get(id).param(0),r.events().stream().filter(e->e.type().equals("TALENT")).findFirst().orElseThrow().states().get(1).statuses().get("talentEclipse"));}}
 @Test void eclipseIgnoresAttackReductionAndConsumesOnFirstOtherDebuff(){var f=pair(List.of(),Map.of("talentEclipse",3))[0];var ch=new ArrayList<Change>();Engine.addStatus(ch,f,"attackReduction",1);assertEquals(3,f.status("talentEclipse"));Engine.addStatus(ch,f,"internalInjury",2);assertEquals(5,f.status("internalInjury"));assertEquals(0,f.status("talentEclipse"));Engine.addStatus(ch,f,"weakness",1);assertEquals(1,f.status("weakness"));}
 @Test void eclipseIsSpentEvenWhenRepelBlocksAllLayers(){var f=pair(List.of(),Map.of("talentEclipse",3,"repel",10))[0];Engine.addStatus(new ArrayList<>(),f,"weakness",1);assertEquals(0,f.status("weakness"));assertEquals(6,f.status("repel"));assertEquals(0,f.status("talentEclipse"));}
 @Test void eclipseAddsToPoisonAndMirrorSeesAmplifiedLayers(){var fs=pair(List.of(256),Map.of("talentEclipse",3));var ch=new ArrayList<Change>();Engine.addStatus(ch,fs[0],"internalInjury",1);assertEquals(4,fs[0].status("internalInjury"));assertEquals(Math.min(4,rules.talentById.get(256).param(0)),fs[1].status("internalInjury"));}
 @Test void starMoonFanDuplicatesSeventhStarWithoutInventingOtherGains(){var s=opened(run("PRE_OPENING",p("A",1000005,List.of(106),Map.of("starMask",64)),idle()));assertEquals(64,s.statuses().get("starMask"));assertEquals(11,s.anima());assertEquals(0,s.statuses().get("starPower"));}
 @Test void fireGenerationChangesBothDirectionsButNotSelfOrNonElement(){var f=pair(List.of(137),Map.of())[0];for(int a=0;a<=5;a++)for(int b=0;b<=5;b++){boolean expected=a>0&&b>0&&(b==a%5+1||((a==4)!=(b==4)));assertEquals(expected,ElementalEffects.generates(f,a,b),a+"->"+b);}}
 @Test void fireTalentChangesAllFiveActiveChecksWithoutFakingActivationCounters(){var f=pair(List.of(137),Map.of("lastElement",4))[0];assertTrue(f.metalActive()&&f.waterActive()&&f.woodActive()&&f.fireActive()&&f.earthActive());assertEquals(0,ElementalEffects.activeCount(f));var g=pair(List.of(137),Map.of("lastElement",1))[0];assertTrue(g.fireActive());assertFalse(g.woodActive());}
 @Test void fireGenerationRewardsExistingCycleTalent(){var f=pair(List.of(137,102),Map.of("lastElement",4))[0];TalentEffects.before(new ArrayList<>(),f,rules.byId.get(7000001),false);assertEquals(rules.talentById.get(102).param(0),f.def);}
 @Test void repeatedActivationExplosionsBypassDefenseAndReduceBothLifeAndCap(){var fs=pair(List.of(138),Map.of());fs[1].def=100;var ch=new ArrayList<Change>();Engine.activate(ch,fs[0],"metalActivation");Engine.activate(ch,fs[0],"metalActivation");int loss=2*rules.talentById.get(138).param(1);assertEquals(400-loss,fs[1].hp);assertEquals(800-loss,fs[1].maxHp);assertEquals(100,fs[1].def);}
 @Test void implicitGenerationDoesNotCountAsActivationExplosion(){var r=run("POST_OPENING",p("A",1000005,List.of(137,138),Map.of("lastElement",4)),idle());assertEquals(400,end(r,1,1).hp());}
 @Test void forgetWorryActivatesWoodAndTriggersOtherOwnedTalents(){var s=opened(run("PRE_OPENING",p("A",1000005,List.of(200,203),Map.of()),idle()));assertEquals(1,s.statuses().get("woodActivation"));assertEquals(802,s.maxHp());}
 @Test void cycleOpeningVariantsGrantTheirOwnCharges(){for(int id:new int[]{127,10127,20127,30127})assertEquals(rules.talentById.get(id).param(1),opened(run("PRE_OPENING",p("A",1000005,List.of(id),Map.of()),idle())).statuses().get("talentCycleUpgrades"));}
 @Test void cycleUpgradeIsPermanentWithinBattleAndSpendsOneCharge(){var r=run("POST_OPENING",p("A",7000001,List.of(137),Map.of("lastElement",4,"talentCycleUpgrades",2)),idle());var s=end(r,1,0);assertEquals(7010001,s.runtimeCards().getFirst());assertEquals(1,s.statuses().get("talentCycleUpgrades"));assertTrue(r.events().stream().anyMatch(e->e.type().equals("TALENT_UPGRADE")&&e.turn()==1));}
 @Test void cycleUpgradeDoesNotSpendOnCappedOrNonGeneratingCards(){for(int card:new int[]{7020001,1000005,7000003}){var s=end(run("POST_OPENING",p("A",card,List.of(),Map.of("lastElement",5,"talentCycleUpgrades",2)),idle()),1,0);assertEquals(card,s.runtimeCards().getFirst());assertEquals(2,s.statuses().get("talentCycleUpgrades"));}}
 @Test void fireGenerationReachesAdjacentFlowAndTwinSeal(){var f=pair(List.of(137),Map.of())[0];f.slot=1;f.cards[0]=7000009;f.cards[1]=7000067;f.cards[2]=7000001;var ch=new ArrayList<Change>();ElementalEffects.after(ch,f,f.opponent,rules.byId.get(7000067),rules);assertEquals(1,f.status("metalActivation"));assertEquals(List.of(7000001),ElementalEffects.generated(f,rules.byId.get(7000067),rules));f.slot=0;f.cards[1]=7000009;ElementalEffects.after(ch,f,f.opponent,rules.byId.get(7000110),rules);assertEquals(rules.byId.get(7000110).param(1),f.def);}
 @Test void fireGenerationReachesPhantomFlow(){var f=pair(List.of(137),Map.of())[0];f.slot=1;f.cards[0]=7000009;f.cards[2]=7000001;SpecialEffects.after(new ArrayList<>(),f,f.opponent,rules.byId.get(295),rules);assertTrue(f.requestChase);assertEquals(1,f.status("metalActivation"));assertEquals(1,f.status("fireActivation"));}
 @Test void activationExplosionAlsoRunsDuringOtherTalentsOpening(){var r=run("PRE_OPENING",p("A",1000005,List.of(138,203),Map.of()),idle());var s=r.events().stream().filter(e->e.type().equals("TALENT")).reduce((a,b)->b).orElseThrow().states().get(1);assertEquals(397,s.hp());assertEquals(797,s.maxHp());}
}
